const app=document.getElementById('app');let token=localStorage.token,user=JSON.parse(localStorage.user||'null');
const api=async(u,opt={})=>{opt.headers={...(opt.headers||{}),...(token?{Authorization:'Bearer '+token}:{})};if(opt.body&&!(opt.body instanceof FormData)){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(opt.body)}const r=await fetch('/api'+u,opt);let d={};try{d=await r.json()}catch{}if(r.status===401&&token&&!u.startsWith('/auth/')){logout();throw Error('Session expired. Please log in again.')}if(!r.ok)throw Error(d.message||'Request failed');return d};
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const toast=m=>{const x=document.createElement('div');x.className='toast';x.textContent=m;document.body.appendChild(x);setTimeout(()=>x.remove(),2600)};
const modules=[['dashboard','🏠','Dashboard'],['chat','🤖','AI Chatbot'],['schedule','📅','Smart Schedule'],['map','🗺️','College Map'],['exam','📚','Exam Preparation'],['pyq','📝','Previous Year Papers'],['quiz','🧠','Quiz & Performance'],['placement','💼','Placement Portal'],['resume','📄','Resume Analysis'],['skills','🎯','Skill Gap & Career'],['interview','🎤','Mock Interview'],['complaints','🛠️','Complaints'],['lost','🔎','Lost & Found'],['events','🎪','Events'],['canteen','🍱','Smart Canteen'],['transport','🚌','Transport'],['groups','👥','Study Groups'],['progress','📊','Progress'],['emergency','🚨','Emergency']];
let authMode='login',authBusy=false;
function login(){app.innerHTML=`<div class="login auth-shell"><div class="auth-showcase"><div class="auth-brand"><span>🎓</span><div><b>CAMP-X</b><small>AI Campus Assistant</small></div></div><div class="auth-showcase-copy"><span class="auth-kicker">YOUR CAMPUS. ONE SMART SPACE.</span><h1>Make every campus day count.</h1><p>Classes, AKTU exam prep, campus services and career growth — connected in one student workspace.</p><div class="auth-feature-list"><span>✓ Smart timetable & study planner</span><span>✓ AKTU PYQs, syllabus & practice</span><span>✓ Career tools and campus services</span></div></div><div class="auth-showcase-foot">Built for focused learning and campus life.</div></div><div class="auth-panel-wrap"><div class="auth-card auth-card-modern"><div class="auth-mobile-brand">🎓 <b>CAMP-X</b></div><div class="auth-trust"><span>🔒</span> Secure student access</div><div class="auth-tabs"><button type="button" id="authTabLogin" onclick="showAuth('login')">Sign in</button><button type="button" id="authTabRegister" onclick="showAuth('register')">Create account</button></div><div id="auth"></div><p class="auth-privacy">Your password is protected using server-side hashing. Never share your sign-in details.</p></div></div></div>`;showAuth('login')}
function showAuth(mode){authMode=mode;const box=document.getElementById('auth');if(!box)return;document.getElementById('authTabLogin')?.classList.toggle('active',mode==='login');document.getElementById('authTabRegister')?.classList.toggle('active',mode==='register');box.innerHTML=`<div class="auth-heading"><h2>${mode==='login'?'Welcome back':'Join your campus workspace'}</h2><p>${mode==='login'?'Sign in to continue where you left off.':'Create an account to personalize your CAMP-X experience.'}</p></div><form id="authForm" class="auth-form" onsubmit="event.preventDefault();submitAuth('${mode}')" novalidate>${mode==='register'?`<label class="auth-label" for="name">Full name</label><input class="field auth-input" id="name" name="name" autocomplete="name" maxlength="80" placeholder="e.g. Aditi Sharma" required>`:''}<label class="auth-label" for="email">${mode==='login'?'Email address':'College / personal email'}</label><input class="field auth-input" id="email" name="email" type="email" autocomplete="email" maxlength="254" placeholder="you@example.com" required><label class="auth-label" for="pass">Password</label><div class="auth-password-wrap"><input class="field auth-input" id="pass" name="password" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" minlength="8" maxlength="128" placeholder="${mode==='login'?'Enter your password':'Create a strong password'}" required><button type="button" class="auth-show-password" onclick="toggleAuthPassword()" aria-label="Show password" id="authEye">Show</button></div>${mode==='register'?`<div class="auth-strength"><div class="auth-strength-track"><i id="authStrengthBar"></i></div><small id="authStrengthText">Use at least 8 characters, with upper/lowercase letters and a number.</small></div><label class="auth-label" for="passConfirm">Confirm password</label><input class="field auth-input" id="passConfirm" type="password" autocomplete="new-password" minlength="8" maxlength="128" placeholder="Re-enter your password" required><div class="auth-profile-grid"><div><label class="auth-label" for="branch">Branch</label><select class="field auth-input" id="branch" required><option value="">Select branch</option><option>CSE</option><option>CSIT</option><option>IT</option><option>AI / ML</option><option>Data Science</option><option>ECE</option><option>Electrical</option><option>Mechanical</option><option>Civil</option><option>Other</option></select></div><div><label class="auth-label" for="year">Current year</label><select class="field auth-input" id="year" required><option value="">Select year</option><option value="1">1st year</option><option value="2">2nd year</option><option value="3">3rd year</option><option value="4">4th year</option></select></div></div>`:''}<div id="authError" class="auth-error" role="alert" hidden></div><button type="submit" id="authSubmit" class="btn auth-submit">${mode==='login'?'Sign in securely':'Create student account'} <span>→</span></button>${mode==='login'?`<div class="auth-hint">Having trouble signing in? Check your email and password, or contact your campus administrator if your account needs help.</div>`:`<div class="auth-hint">By creating an account, you agree to use campus resources responsibly. Use an email address you can access.</div>`}</form>`;const pass=document.getElementById('pass');pass?.addEventListener('input',updatePasswordStrength);document.getElementById('email')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&mode==='login')document.getElementById('pass')?.focus()});}
function toggleAuthPassword(){const p=document.getElementById('pass'),b=document.getElementById('authEye');if(!p||!b)return;const reveal=p.type==='password';p.type=reveal?'text':'password';b.textContent=reveal?'Hide':'Show';b.setAttribute('aria-label',reveal?'Hide password':'Show password')}
function updatePasswordStrength(){const p=document.getElementById('pass')?.value||'',checks=[p.length>=8,/[A-Z]/.test(p),/[a-z]/.test(p),/\d/.test(p),/[^A-Za-z0-9]/.test(p)],score=checks.filter(Boolean).length,bar=document.getElementById('authStrengthBar'),txt=document.getElementById('authStrengthText');if(bar){bar.style.width=(score*20)+'%';bar.dataset.level=score<=2?'weak':score<=3?'fair':score<=4?'good':'strong'}if(txt)txt.textContent=score<=2?'Weak — add length and mix character types.':score<=3?'Fair — add uppercase/lowercase letters and a number.':score===4?'Good — a symbol can make it stronger.':'Strong password format.'}
async function submitAuth(mode){if(authBusy)return;const email=(document.getElementById('email')?.value||'').trim(),password=document.getElementById('pass')?.value||'',err=document.getElementById('authError'),btn=document.getElementById('authSubmit');const fail=m=>{if(err){err.textContent=m;err.hidden=false}else toast(m)};if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return fail('Enter a valid email address.');if(!password)return fail('Enter your password.');if(mode==='register'){const name=(document.getElementById('name')?.value||'').trim(),confirm=document.getElementById('passConfirm')?.value||'';if(name.length<2)return fail('Enter your full name (at least 2 characters).');if(password.length<8||!/[A-Z]/.test(password)||!/[a-z]/.test(password)||!/[0-9]/.test(password))return fail('Use at least 8 characters with uppercase, lowercase and a number.');if(password!==confirm)return fail('The passwords do not match.');if(!document.getElementById('branch')?.value||!document.getElementById('year')?.value)return fail('Choose your branch and current year.')}if(err)err.hidden=true;authBusy=true;if(btn){btn.disabled=true;btn.innerHTML='<span class="auth-spinner"></span> Please wait…'}try{const d=await api('/auth/'+mode,{method:'POST',body:{name:document.getElementById('name')?.value?.trim()||'',email,password,branch:document.getElementById('branch')?.value||'',year:document.getElementById('year')?.value||''}});token=d.token;user=d.user;localStorage.token=token;localStorage.user=JSON.stringify(user);render()}catch(e){fail(e.message||'Authentication failed. Please try again.')}finally{authBusy=false;if(btn&&document.body.contains(btn)){btn.disabled=false;btn.innerHTML=`${mode==='login'?'Sign in securely':'Create student account'} <span>→</span>`}}}
function render(){app.innerHTML=`<div class="shell"><aside class="side" id="side"><div class="brand"><div class="brand-icon">🎓</div><div><h2>AI Campus</h2><small>Student ecosystem</small></div></div><div class="nav-section">Workspace</div>${modules.slice(0,10).map(m=>`<button class="nav" data-nav="${m[0]}" onclick="page('${m[0]}')"><span>${m[1]}</span>${m[2]}</button>`).join('')}<div class="nav-section">Services</div>${modules.slice(10).map(m=>`<button class="nav" data-nav="${m[0]}" onclick="page('${m[0]}')"><span>${m[1]}</span>${m[2]}</button>`).join('')}<button class="nav" onclick="logout()">🚪 Logout</button></aside><main class="main"><header class="topbar"><div><button class="btn ghost mobile-menu" onclick="document.getElementById('side').classList.toggle('open')">☰</button><div class="eyebrow">Connected campus</div><h1 id="title">Dashboard</h1><span class="muted" id="subtitle">Your personalized student workspace</span></div><div class="user-chip"><div class="avatar">${esc((user?.name||'S').slice(0,1).toUpperCase())}</div><div><b>${esc(user?.name||'Student')}</b><br><small class="muted">${esc(user?.branch||'Student')}</small></div></div></header><section id="content"></section></main></div>`;page('dashboard')}
function logout(){localStorage.removeItem('token');localStorage.removeItem('user');token=null;user=null;login()}
async function page(p){document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.nav===p));document.getElementById('side')?.classList.remove('open');document.getElementById('title').textContent=modules.find(x=>x[0]===p)?.[2]||p;const c=document.getElementById('content');c.innerHTML='<div class="loading">Loading your campus data…</div>';try{const f={dashboard,chat,schedule,map,exam,pyq,quiz,placement:()=>placement(c),resume,skills,interview,progress,complaints:()=>crudPage(c,'complaints','Complaints','title,description,location,status'),lost:()=>crudPage(c,'lost-found','Lost & Found','title,description,location,date,status'),events:()=>crudPage(c,'events','Campus Events','title,type,date,location,interest'),canteen:()=>crudPage(c,'canteen','Canteen Menu','item,price,prepTime,category'),transport:()=>crudPage(c,'transport','Transport Routes','route,pickupTime,delay,status'),groups:()=>crudPage(c,'groups','Study Groups','subject,description,time,maxMembers'),emergency};return await f[p](c)}catch(e){c.innerHTML=`<div class="card"><h3>Something went wrong</h3><p class="muted">${esc(e.message)}</p></div>`}}

async function schedule(c){
  let savedSection=localStorage.getItem('campx_timetable_section')||'';
  const allSections=Object.keys(window.CAMPUS_TIMETABLES||{});
  const branch=String(user?.branch||'').toUpperCase();
  const year=String(user?.year||'').toUpperCase();
  const guess=allSections.find(s=>(!savedSection)&&((branch.includes('IT')&&s.includes('IT'))||(branch.includes('CS')&&s.includes('CSIT')))&&((year.includes('3')||year.includes('III'))?s.startsWith('III'):((year.includes('2')||year.includes('V'))?s.startsWith('V'):((year.includes('4')||year.includes('VII'))?s.startsWith('VII'):false))));
  let section=savedSection||guess||allSections[0]||'';
  let activeDay=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][((new Date().getDay()+6)%7)];
  let tasks=[];
  try{tasks=(await api('/schedules')).filter(x=>x.userId===user?.id&&(x.type==='study-task'||x.type==='personal-event'));}catch(e){}
  const today=new Date(); const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const escv=esc;
  c.innerHTML=`<div class="schedule-page">
    <div class="card hero schedule-hero"><div><div class="eyebrow" style="color:#c4b5fd">YOUR WEEK, ORGANIZED</div><h2>📅 Smart Schedule</h2><p class="muted">Your official class timetable + personal study planner in one place.</p></div><div class="schedule-hero-badge">✨ Smart planning</div></div>
    <div class="schedule-stats grid">
      <div class="card mini-stat"><span class="muted">Classes today</span><strong id="ssClasses">—</strong><small class="muted">From your selected timetable</small></div>
      <div class="card mini-stat"><span class="muted">Study tasks pending</span><strong id="ssPending">—</strong><small class="muted">Your personal plan</small></div>
      <div class="card mini-stat"><span class="muted">Next deadline</span><strong id="ssDeadline">—</strong><small class="muted">Closest unfinished task</small></div>
    </div>
    <div class="card">
      <div class="section-head"><div><h2>🏫 Class timetable</h2><p class="muted">Imported from the 2026–27 ODD semester master timetable.</p></div><select id="ssSection" class="field schedule-section">${allSections.map(s=>`<option value="${escv(s)}" ${s===section?'selected':''}>${escv(s)}</option>`).join('')}</select></div>
      <div class="schedule-day-tabs" id="ssDays"><button data-day="Week" class="schedule-day ${activeDay==='Week'?'active':''}" onclick="ssSetDay('Week')">Week</button>${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>`<button data-day="${d}" class="schedule-day ${d===activeDay?'active':''}" onclick="ssSetDay('${d}')">${d.slice(0,3)}</button>`).join('')}</div>
      <div id="ssTimetable"></div>
      <p class="schedule-footnote">Timetable source: Master time table 2026–27 final ODD sem. Confirm any room/period changes with your department.</p>
    </div>
    <div class="grid schedule-lower">
      <div class="card">
        <div class="section-head"><div><h2>🧠 Smart study planner</h2><p class="muted">Set a goal and deadline; Camp-X schedules focused sessions after classes.</p></div></div>
        <form id="ssTaskForm" class="smart-task-form">
          <label>Subject / task<input id="ssTitle" class="field" required maxlength="100" placeholder="e.g. Revise Data Structures"></label>
          <div class="form-grid"><label>Deadline<input id="ssDue" class="field" type="date" min="${iso(today)}" required value="${iso(new Date(today.getTime()+3*86400000))}"></label><label>Estimated effort<select id="ssDuration" class="field"><option value="60">1 hour</option><option value="90">1.5 hours</option><option value="120">2 hours</option><option value="180">3 hours</option></select></label></div>
          <label>Priority<select id="ssPriority" class="field"><option value="high">High — exam / urgent</option><option value="medium" selected>Medium</option><option value="low">Low</option></select></label>
          <button class="btn" type="submit">✨ Create smart plan</button>
        </form>
        <div id="ssPlanMessage" class="muted small" style="margin-top:12px"></div>
      </div>
      <div class="card">
        <div class="section-head"><div><h2>✅ Your tasks</h2><p class="muted">Deadlines, planned study blocks and completion tracking.</p></div><span class="pill" id="ssTaskCount">0 tasks</span></div>
        <div id="ssTasks"></div>
      </div>
    </div>
  </div>`;
  document.getElementById('ssSection').addEventListener('change',e=>{section=e.target.value;localStorage.setItem('campx_timetable_section',section);ssRenderTimetable();});
  document.getElementById('ssTaskForm').addEventListener('submit',async e=>{
    e.preventDefault();
    const title=document.getElementById('ssTitle').value.trim(), due=document.getElementById('ssDue').value, duration=Number(document.getElementById('ssDuration').value), priority=document.getElementById('ssPriority').value;
    if(!title||!due)return;
    const plan=ssBuildPlan(due,duration,priority);
    if(!plan.length){document.getElementById('ssPlanMessage').textContent='No free evening slot found before this deadline. Choose a later deadline or a shorter effort estimate.';return;}
    try{
      const created=[];
      for(let i=0;i<plan.length;i++){
        const block=plan[i];
        const item=await api('/schedules',{method:'POST',body:{type:'study-task',title,subject:title,date:block.date,startTime:block.start,endTime:block.end,notes:`Smart plan · ${priority} priority · Session ${i+1}/${plan.length}`,priority,status:'pending',userId:user?.id}});
        created.push(item);
      }
      tasks=tasks.concat(created);ssRenderTasks();ssUpdateStats();
      document.getElementById('ssPlanMessage').textContent=`Plan created: ${plan.length} focused session${plan.length>1?'s':''}, ${duration} minutes total, before ${due}.`;
      document.getElementById('ssTitle').value='';toast('Smart study plan created');
    }catch(err){toast(err.message||'Could not save plan');}
  });
  window.ssSetDay=d=>{activeDay=d;ssRenderTimetable();};
  function ssRenderTimetable(){
    document.querySelectorAll('.schedule-day').forEach(b=>b.classList.toggle('active',b.dataset.day===activeDay));
    const el=document.getElementById('ssTimetable'); if(!el)return;
    const all=window.CAMPUS_TIMETABLES?.[section]||{};
    const renderEntries=entries=>entries.map(x=>{
      const lower=x.subject.toLowerCase();
      const kind=(lower.includes('lunch')||lower.includes('mentorship')||lower.includes('break'))?'break':lower.includes('lab')||lower.includes('practical')?'lab':'class';
      const lines=x.subject.split('\n');
      return `<div class="timetable-row"><div class="time-col">${escv(x.time)}</div><div class="timeline-dot ${kind}"></div><div class="timetable-subject ${kind}"><div class="subject-top"><strong>${escv(lines[0])}</strong><span class="pill">${kind==='lab'?'PRACTICAL':kind==='break'?'BREAK':'CLASS'}</span></div>${lines.length>1?`<small class="muted">${escv(lines.slice(1).join(' · '))}</small>`:''}</div></div>`;
    }).join('');
    if(activeDay==='Week'){
      const weekdays=['Monday','Tuesday','Wednesday','Thursday','Friday'];
      el.innerHTML=`<div class="timetable-week-grid">${weekdays.map(day=>{
        const entries=all[day]||[];
        return `<section class="timetable-week-day"><div class="timetable-week-heading"><h3>${day}</h3><span class="pill">${entries.filter(x=>!/(lunch|mentorship|break)/i.test(x.subject)).length} classes</span></div>${entries.length?`<div class="timetable-list">${renderEntries(entries)}</div>`:`<div class="empty">No entries listed</div>`}</section>`;
      }).join('')}</div>`;
      return;
    }
    const entries=all[activeDay]||[];
    if(!entries.length){el.innerHTML=`<div class="empty">No class entries listed for ${activeDay}. Use this as a planning / self-study day.</div>`;return;}
    el.innerHTML=`<div class="timetable-list">${renderEntries(entries)}</div>`;
  }
  function ssBuildPlan(due,duration,priority){
    const blocks=[];const start=new Date();start.setHours(0,0,0,0);const end=new Date(due+'T00:00:00');
    const minutesPerSession=duration>120?60:Math.min(60,duration);
    for(let d=new Date(start);d<=end&&blocks.reduce((n,b)=>n+b.minutes,0)<duration;d.setDate(d.getDate()+1)){
      if(d.getTime()===start.getTime()&&new Date().getHours()>=19)continue;
      const day=d.getDay();if(day===0)continue;
      const date=iso(d);const existing=tasks.filter(t=>t.date===date&&t.status!=='done').sort((a,b)=>String(a.startTime).localeCompare(String(b.startTime)));
      let cursor=16*60+30; // 4:30 PM, after scheduled campus classes
      const minutesNeeded=Math.min(minutesPerSession,duration-blocks.reduce((n,b)=>n+b.minutes,0));
      let found=false;
      while(cursor+minutesNeeded<=21*60){
        const st=ssClock(cursor), en=ssClock(cursor+minutesNeeded);
        const clash=existing.some(t=>t.startTime&&t.endTime&&cursor<ssMins(t.endTime)&&cursor+minutesNeeded>ssMins(t.startTime))||blocks.some(t=>t.date===date&&cursor<ssMins(t.end)&&cursor+minutesNeeded>ssMins(t.start));
        if(!clash){blocks.push({date,start:st,end:en,minutes:minutesNeeded});found=true;break;}
        cursor+=30;
      }
      if(!found)continue;
    }
    return blocks;
  }
  function ssClock(m){return `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`}
  function ssMins(s){if(!s)return 0;const a=String(s).split(':').map(Number);return a[0]*60+(a[1]||0)}
  function ssRenderTasks(){
    const el=document.getElementById('ssTasks');if(!el)return;
    const ordered=[...tasks].sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))||String(a.startTime||'').localeCompare(String(b.startTime||'')));
    document.getElementById('ssTaskCount').textContent=`${ordered.length} task${ordered.length===1?'':'s'}`;
    if(!ordered.length){el.innerHTML='<div class="empty">No study tasks yet. Add a goal to build your first smart plan.</div>';return;}
    el.innerHTML=ordered.map(t=>`<div class="smart-task ${t.status==='done'?'completed':''}"><div class="task-check"><button class="check-btn" title="Mark complete" onclick="ssToggleTask('${escv(t.id)}')">${t.status==='done'?'✓':'○'}</button></div><div class="task-body"><strong>${escv(t.title)}</strong><div class="muted small">${escv(t.date||'No date')} · ${escv(t.startTime||'')}–${escv(t.endTime||'')}</div><div class="task-meta"><span class="priority ${escv(t.priority||'medium')}">${escv(t.priority||'medium')} priority</span><span class="muted small">${escv(t.notes||'')}</span></div></div><button class="task-delete" title="Delete task" onclick="ssDeleteTask('${escv(t.id)}')">×</button></div>`).join('');
  }
  window.ssToggleTask=async id=>{const t=tasks.find(x=>String(x.id)===String(id));if(!t)return;try{const updated=await api('/schedules/'+encodeURIComponent(id),{method:'PUT',body:{...t,status:t.status==='done'?'pending':'done'}});tasks=tasks.map(x=>String(x.id)===String(id)?updated:x);ssRenderTasks();ssUpdateStats();}catch(e){toast(e.message)}};
  window.ssDeleteTask=async id=>{try{await api('/schedules/'+encodeURIComponent(id),{method:'DELETE'});tasks=tasks.filter(x=>String(x.id)!==String(id));ssRenderTasks();ssUpdateStats();toast('Task deleted')}catch(e){toast(e.message)}};
  function ssUpdateStats(){
    const todayStr=iso(new Date()),todayName=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][new Date().getDay()];
    const count=(window.CAMPUS_TIMETABLES?.[section]?.[todayName]||[]).filter(x=>!/(lunch|break|mentorship)/i.test(x.subject)).length;
    document.getElementById('ssClasses').textContent=count;
    const pending=tasks.filter(t=>t.status!=='done');document.getElementById('ssPending').textContent=pending.length;
    const next=pending.filter(t=>t.date>=todayStr).sort((a,b)=>a.date.localeCompare(b.date))[0];
    document.getElementById('ssDeadline').textContent=next?next.date.slice(5):'—';
  }
  ssRenderTimetable();ssRenderTasks();ssUpdateStats();
}

