function chat(c){const secs=Object.keys(window.CAMPUS_TIMETABLES||{}),saved=localStorage.getItem('campx_timetable_section')||'';c.innerHTML=`<div class="card"><div class="actions" style="justify-content:space-between"><div><h2>🤖 AI Campus Assistant</h2><p class="muted">Database-connected answers for classes, subjects, campus services and your study plan.</p></div><span class="pill">Grounded assistant</span></div><div class="field-row" style="margin:14px 0"><label for="chatSection">Your timetable section</label><select class="field" id="chatSection"><option value="">Choose section…</option>${secs.map(s=>`<option value="${esc(s)}" ${s===saved?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="actions" style="margin-bottom:12px"><button class="btn ghost" onclick="chatPrompt('What classes do I have today?')">📅 Today’s classes</button><button class="btn ghost" onclick="chatPrompt('Explain a subject concept with an example and practice question')">📘 Explain a subject</button><button class="btn ghost" onclick="chatPrompt('Show the latest campus notices and events')">📢 Notices & events</button></div><div id="chat" class="chat" aria-live="polite"></div><div class="chat-input"><input class="field" id="msg" placeholder="Ask about classes, DBMS, DSA, campus…" onkeydown="if(event.key==='Enter')sendChat()"><button class="btn" id="chatSend" onclick="sendChat()">Send ↑</button></div><p class="muted" style="font-size:12px;margin-top:10px">Campus facts come from saved records and the imported timetable. Add an AI API key in backend/.env for advanced tutoring and natural-language answers.</p></div>`;document.getElementById('chatSection').addEventListener('change',e=>{if(e.target.value)localStorage.setItem('campx_timetable_section',e.target.value)});loadChat()}
function chatPrompt(q){const m=document.getElementById('msg');if(m){m.value=q;m.focus();}}
async function loadChat(){const x=document.getElementById('chat');if(!x)return;try{const h=await api('/chatbot/history');x.innerHTML=h.map(m=>`<div class="bubble me">${esc(m.message)}</div><div class="bubble bot">${esc(m.answer).replace(/\n/g,'<br>')}<br><small class="muted">${m.provider==='database-grounded-ai'?'AI · database-grounded':m.provider==='database-retrieval'?'Database lookup':'Campus knowledge base'}</small></div>`).join('')||'<div class="empty">Start with a suggested question or ask your own.</div>';x.scrollTop=x.scrollHeight}catch(e){x.innerHTML=`<div class="empty">Could not load chat history: ${esc(e.message)}</div>`}}
async function sendChat(){const m=document.getElementById('msg'),btn=document.getElementById('chatSend');if(!m||!m.value.trim())return;const v=m.value.trim(),section=document.getElementById('chatSection')?.value||localStorage.getItem('campx_timetable_section')||'';m.value='';if(btn){btn.disabled=true;btn.textContent='Thinking…'}try{const r=await api('/chatbot',{method:'POST',body:{message:v,section}});await loadChat()}catch(e){toast(e.message);m.value=v}finally{if(btn){btn.disabled=false;btn.textContent='Send ↑'}}}
