function populatePYQSubjects(){
  const sel=document.getElementById('pyqSubject');if(!sel)return;
  const map={'All subjects':'','BEE101':'Fundamentals of Electrical Engineering','BCS101':'Programming for Problem Solving','BEC101':'Fundamentals of Electronics Engineering','BAS101':'Engineering Physics','BAS102':'Engineering Chemistry','BAS103':'Engineering Mathematics-I','BAS104':'Environment and Ecology','BAS105':'Soft Skills'};
  sel.innerHTML='<option value="">All subjects</option>'+Object.entries(map).filter(([k])=>k!=='All subjects').map(([code,name])=>`<option value="${esc(code)}">${esc(code)} · ${esc(name)}</option>`).join('');
}
async function loadPYQ(){
  const box=document.getElementById('pyqList');if(!box)return;
  box.innerHTML='<div class="card"><div class="loading">Loading papers from the database…</div></div>';
  const branch=document.getElementById('pyqBranch')?.value||'COMMON',year=document.getElementById('pyqYear')?.value||'',semester=document.getElementById('pyqSem')?.value||'',subject=document.getElementById('pyqSubject')?.value||'',q=document.getElementById('pyqSearch')?.value||'';
  try{
    const params=new URLSearchParams();if(branch)params.set('branch',branch);if(year)params.set('year',year);if(semester)params.set('semester',semester);if(subject)params.set('subject',subject);if(q.trim())params.set('q',q.trim());
    const d=await api('/pyq?'+params.toString());const items=d.items||[];
    const yearSelect=document.getElementById('pyqYear');if(yearSelect&&Array.isArray(d.availableYears)){const selectedYear=yearSelect.value;const years=[...new Set(d.availableYears)].sort((a,b)=>String(b).localeCompare(String(a)));yearSelect.innerHTML='<option value="">All exam years</option>'+years.map(y=>`<option value="${esc(y)}">${esc(y)}</option>`).join('');yearSelect.value=years.includes(selectedYear)?selectedYear:'';}
    const subjectSelect=document.getElementById('pyqSubject');if(subjectSelect&&Array.isArray(d.subjectOptions)){const selectedSubject=subjectSelect.value;subjectSelect.innerHTML='<option value="">All subjects</option>'+d.subjectOptions.map(x=>`<option value="${esc(x.code)}">${esc(x.code)} · ${esc(x.name)}</option>`).join('');subjectSelect.value=d.subjectOptions.some(x=>x.code===selectedSubject)?selectedSubject:'';}
    window.__pyq=items;window.__pyqBranch=branch;window.__pyqSubject=subject;
    renderPYQ(items);renderPYQStats(items,branch,year,semester,d.count||0);
  }catch(e){box.innerHTML=`<div class="card"><h3>Could not load PYQ database</h3><p class="muted">${esc(e.message)}</p><p class="muted">Start the backend with <code>cd backend && npm install && npm start</code>, then sign in again.</p></div>`}
}
function renderPYQStats(items,branch,year,semester,total=items.length){
  const stats=document.getElementById('pyqStats');if(!stats)return;
  const years=[...new Set(items.map(x=>x.year))].sort().join(', ')||'—';
  const pages=items.reduce((n,x)=>n+(Number(x.pages)||0),0);
  const answerKeys=items.filter(x=>x.answerKeyAvailable||x.verifiedOfficialAnswerKey).length;
  stats.innerHTML=`<div class="grid"><div class="card"><div class="metric-label">Papers in database</div><div class="stat">${total}</div></div><div class="card"><div class="metric-label">Matching papers</div><div class="stat">${items.length}</div></div><div class="card"><div class="metric-label">PDF pages in results</div><div class="stat">${pages}</div></div><div class="card"><div class="metric-label">Answer keys supplied</div><div class="stat">${answerKeys}</div><small class="muted">No key is assumed when absent</small></div></div><p class="muted" style="margin-top:8px">Exam years represented in these results: ${esc(years)}. The library includes first-year papers and subject-wise Semester III–IV archives; year, semester, branch and text filters use the bundled database.</p>`;
}
function renderPYQ(papers){
  const box=document.getElementById('pyqList');if(!box)return;
  box.innerHTML=papers.map((x,i)=>`<div class="card"><div class="actions" style="justify-content:space-between"><span class="pill">${esc(x.year||'Exam year')} · Semester ${esc(x.semester||1)}</span><span class="pill">${esc(x.subjectCode||'Subject')}</span></div><h3 style="margin-top:12px">${esc(x.subject||x.title||'Previous Year Paper')}</h3><p class="muted">${esc(x.examType||'B.Tech Theory Examination')} · ${esc(x.pages||'?')} pages</p><p>${esc(x.note||'Original uploaded question paper.')}</p><p class="muted">${x.textExtracted?'Question text indexed for search':'Scanned PDF: question text could not be extracted automatically'} · ${esc(x.questionCount||0)} indexed question lines</p><div class="actions"><a class="btn" href="${esc(x.downloadUrl||x.fileUrl)}" target="_blank" rel="noopener">📄 Open PDF</a><a class="btn secondary" href="${esc(x.downloadUrl||x.fileUrl)}" download>⬇️ Download</a><button class="btn ghost" onclick="showPYQDetails(${i})">📋 Paper details</button></div><small class="muted" style="display:block;margin-top:10px">${x.answerKeyAvailable||x.verifiedOfficialAnswerKey?'✅ Answer key supplied':'ℹ️ No answer key supplied with this PDF'} · ${esc(x.source||'Uploaded paper')}</small><div id="pyqDetails${i}"></div></div>`).join('')||'<div class="card"><div class="empty">No papers match these filters. Try another year or subject.</div></div>';
}
async function showPYQDetails(i){
  const p=(window.__pyq||[])[i],box=document.getElementById('pyqDetails'+i);if(!p||!box)return;
  box.innerHTML=`<div class="list-item" style="margin-top:12px"><b>${esc(p.subjectCode)} · ${esc(p.year)}</b><p class="muted">Paper ID: ${esc(p.id)} · ${esc(p.sourceFileName||'Bundled PDF')}</p><p class="muted">SHA-256 file integrity hash is stored in the database manifest.</p><h4 style="margin-top:12px">Answer key contributions</h4><p class="muted">Only entries reviewed by a CAMP-X admin are marked verified. Do not treat pending contributions as official answers.</p><div id="pyqKeys${i}"><span class="muted">Loading answer contributions…</span></div><h4 style="margin-top:14px">Contribute an answer / solution</h4><div class="form-grid"><textarea class="field full" id="keyQuestion${i}" rows="2" placeholder="Question number or exact question"></textarea><textarea class="field full" id="keyAnswer${i}" rows="3" placeholder="Proposed answer / solution"></textarea><textarea class="field full" id="keyExplanation${i}" rows="2" placeholder="Working / explanation (optional)"></textarea><input class="field full" id="keySource${i}" placeholder="Source or reference (optional; e.g. textbook + chapter)"></div><button class="btn" style="margin-top:8px" onclick="submitPYQAnswerKey(${i})">Submit for review</button><div id="keyNotice${i}" class="muted" style="margin-top:8px"></div></div>`;
  await loadPYQAnswerKeys(i);
}
async function loadPYQAnswerKeys(i){const p=(window.__pyq||[])[i],box=document.getElementById('pyqKeys'+i);if(!p||!box)return;try{const d=await api(`/pyq/${encodeURIComponent(p.id)}/answer-keys`);const items=d.items||[];box.innerHTML=items.length?items.map(x=>`<div class="list-item" style="margin-top:8px"><div class="actions" style="justify-content:space-between"><b>${esc(x.question)}</b><span class="pill">${x.status==='verified'?'Verified':x.status==='rejected'?'Rejected':'Pending review'}</span></div><p><b>Proposed answer:</b> ${esc(x.answer)}</p>${x.explanation?`<p>${esc(x.explanation)}</p>`:''}<small class="muted">Submitted by ${esc(x.userName||'Student')} · ${esc(x.source||'No source supplied')}</small>${x.status==='verified'?`<p class="muted">Reviewed ${esc(x.verifiedAt?new Date(x.verifiedAt).toLocaleDateString():'')}</p>`:''}${x.canVerify?`<button class="btn secondary" style="margin-top:8px" onclick="verifyPYQAnswerKey('${esc(x.id)}',true,${i})">Verify answer</button> <button class="btn ghost" style="margin-top:8px" onclick="verifyPYQAnswerKey('${esc(x.id)}',false,${i})">Reject</button>`:''}</div>`).join(''):'<p class="muted">No answer contributions yet. You can submit a solution for review.</p>'}catch(e){box.innerHTML=`<p class="muted">${esc(e.message)}</p>`}}
async function submitPYQAnswerKey(i){const p=(window.__pyq||[])[i],notice=document.getElementById('keyNotice'+i);if(!p)return;const question=document.getElementById('keyQuestion'+i).value.trim(),answer=document.getElementById('keyAnswer'+i).value.trim(),explanation=document.getElementById('keyExplanation'+i).value.trim(),source=document.getElementById('keySource'+i).value.trim();if(!question||!answer){notice.textContent='Enter a question reference and proposed answer.';return}try{const d=await api(`/pyq/${encodeURIComponent(p.id)}/answer-keys`,{method:'POST',body:{question,answer,explanation,source}});notice.textContent=d.message||'Submitted for review.';document.getElementById('keyQuestion'+i).value='';document.getElementById('keyAnswer'+i).value='';document.getElementById('keyExplanation'+i).value='';document.getElementById('keySource'+i).value='';await loadPYQAnswerKeys(i)}catch(e){notice.textContent=e.message}}
async function verifyPYQAnswerKey(keyId,approve,i){try{await api(`/pyq/answer-keys/${encodeURIComponent(keyId)}/verify`,{method:'POST',body:{approve}});toast(approve?'Answer marked verified':'Contribution rejected');await loadPYQAnswerKeys(i)}catch(e){toast(e.message)}}
function selectedPYQSubject(){
  const sel=document.getElementById('pyqSubject');
  if(!sel||!sel.value)return null;
  const code=sel.value;
  const option=[...sel.options].find(o=>o.value===code);
  return {code,label:option?.textContent||code};
}
async function requestSubjectPYQAnalysis(){
  const subject=selectedPYQSubject();
  if(!subject){toast('Select an individual subject first to analyse all of its previous-year papers.');return null;}
  const branch=document.getElementById('pyqBranch')?.value||'ALL';
  const params=new URLSearchParams({subjectCode:subject.code});
  if(branch&&branch!=='ALL')params.set('branch',branch);
  // Deliberately do not pass exam year or semester: analysis covers every stored year for this subject.
  return await api('/pyq/analysis/subject?'+params.toString());
}
function subjectAnalysisHtml(d){
  const escYears=x=>(x.years||[]).map(esc).join(', ');
  const exact=d.repeatedQuestions||[],similar=d.repeatedSimilar||[],topics=d.topics||[];
  const questionList=(items,similarity=false)=>items.length?`<div class="list">${items.slice(0,10).map(x=>`<div class="list-item"><b>${esc(x.question)}</b><p class="muted">Repeated across ${Number(x.yearCount||new Set((x.papers||[]).map(p=>String(p.year||'')).filter(Boolean)).size)} years: ${escYears(x)}${similarity?' · similar wording':''}</p></div>`).join('')}</div>`:'<p class="muted">No reliable cross-year repeats found in the indexed papers.</p>';
  const topicList=topics.length?`<div class="grid-2">${topics.slice(0,10).map(x=>{const n=Number(x.yearCount||(x.years||[]).length);const level=n>=4?'High priority':n>=3?'Priority':'Recurring';return `<div class="list-item"><div class="actions" style="justify-content:space-between;gap:8px"><b>${esc(x.topic)}</b><span class="pill">${level}</span></div><p class="muted">Appears across ${n} years: ${escYears(x)}</p></div>`}).join('')}</div>`:'<p class="muted">No multi-word topic was found in two or more distinct exam years.</p>';
  return `<div class="card"><div class="eyebrow">CROSS-YEAR REPEAT FINDER</div><h3>${esc(d.subjectCode||'')} · ${esc(d.subject||'Subject')}</h3><p class="muted">Showing only questions and topic patterns that recur across different years.</p><h4 style="margin-top:16px">🔥 Repeated questions</h4>${questionList(exact)}<h4 style="margin-top:18px">🧠 Repeated question patterns</h4>${questionList(similar,true)}<h4 style="margin-top:18px">🎯 Topics to prioritize</h4>${topicList}<p class="muted" style="margin-top:12px">${esc(d.notice||'Based on the available extracted PYQ text; this is a revision guide, not a prediction.')}</p></div>`;
}
async function findRepeatedPYQ(){
  const box=document.getElementById('pyqPriority');if(!box)return;box.innerHTML='<div class="card"><div class="loading">Comparing this subject across all available years…</div></div>';
  try{const d=await requestSubjectPYQAnalysis();if(d)box.innerHTML=subjectAnalysisHtml(d)}catch(e){box.innerHTML=`<div class="card"><p class="muted">${esc(e.message)}</p></div>`}
}
async function pyqAITrends(){
  const box=document.getElementById('pyqAI');if(!box)return;box.innerHTML='<div class="card"><div class="loading">Analysing all stored years for the selected subject…</div></div>';
  try{const d=await requestSubjectPYQAnalysis();if(d)box.innerHTML=subjectAnalysisHtml(d)}catch(e){box.innerHTML=`<div class="card"><p class="muted">${esc(e.message)}</p></div>`}
}
