let activeQuiz=null,activeQuizAnswers={},quizTimer=null,quizTimedOut=false;
function quizSubjectOptions(d){const pyq=(d.pyqSubjects||[]).map(x=>{const years=(x.years||[]).slice(0,2).join(', ');const range=years?` · ${years}${(x.years||[]).length>2?'…':''}`:'';return `<option value="${esc(x.code||x.name)}" data-code="${esc(x.code||'')}" data-name="${esc(x.name||x.code)}">${esc(x.code?x.code+' — '+x.name:x.name)} · ${Number(x.paperCount)||0} papers${esc(range)}</option>`});const seen=new Set((d.pyqSubjects||[]).map(x=>String(x.name||'').toLowerCase()));const fallback=(d.subjects||[]).filter(x=>!seen.has(String(x).toLowerCase())).map(x=>`<option value="${esc(x)}" data-code="" data-name="${esc(x)}">${esc(x)} · practice bank</option>`);return [...pyq,...fallback].join('')}
async function quiz(c){
 c.innerHTML=`<div class="card hero"><div class="eyebrow" style="color:#c4b5fd">AKTU B.Tech · PYQ-grounded practice</div><h2>🧠 Quiz & Performance</h2><p class="muted">Choose your branch and subject. When AI is configured, CAMP-X analyses the stored papers for that subject, prioritizes recurring questions and topics, and generates original MCQs with explanations. Your results reveal weak topics over time.</p><div class="form-grid" style="margin-top:16px"><select class="field" id="quizBranch" aria-label="Branch"></select><select class="field" id="quizSubject" aria-label="Subject"><option>Loading subjects…</option></select><select class="field" id="quizSection" aria-label="Class section"><option value="">Any class section</option></select><select class="field" id="quizDifficulty"><option value="Mixed">Mixed difficulty</option><option>Easy</option><option>Medium</option><option>Hard</option></select><select class="field" id="quizCount"><option value="5">5 questions</option><option value="10" selected>10 questions</option><option value="15">15 questions</option><option value="20">20 questions</option></select><select class="field" id="quizMode"><option value="practice">Practice mode · untimed</option><option value="exam">Exam mode · 90 sec/question</option></select></div><div class="actions" style="margin-top:12px"><button class="btn" onclick="suggestQuizTopics()">🎯 Suggest repeated topics</button><button class="btn" onclick="startAKTUQuiz()">Generate PYQ-based quiz</button><button class="btn secondary" onclick="loadQuizHistory()">📊 Refresh performance</button></div><div id="quizNotice" class="muted" style="margin-top:10px"></div><div id="quizTopicSuggestions" style="margin-top:12px"></div></div><div id="quizArea" style="margin-top:18px"></div><div id="quizPerformance" style="margin-top:18px"></div>`;
 try{const d=await api('/quiz/options');const branch=document.getElementById('quizBranch'),sub=document.getElementById('quizSubject'),sec=document.getElementById('quizSection');branch.innerHTML=(d.branches||['ALL','CSE','IT','AIML','AI','DS','IOT','ECE','ME','EE']).map(x=>`<option value="${esc(x)}" ${x===(d.branch||'ALL')?'selected':''}>${x==='ALL'?'All branches':esc(x)}</option>`).join('');sec.innerHTML='<option value="">Any class section</option>'+d.sections.map(x=>`<option value="${esc(x)}" ${x===d.section?'selected':''}>${esc(x)}</option>`).join('');sub.innerHTML=quizSubjectOptions(d);if(!d.pyqSubjects?.length)sub.innerHTML='<option value="">No PYQ subject for this branch</option>'+sub.innerHTML;branch.onchange=async()=>{try{const n=await api('/quiz/options?branch='+encodeURIComponent(branch.value)+'&section='+encodeURIComponent(sec.value));sub.innerHTML=quizSubjectOptions(n);if(!n.pyqSubjects?.length)document.getElementById('quizNotice').textContent='No stored subject papers for this branch yet. Practice-bank subjects may still be available.';else document.getElementById('quizNotice').textContent=n.source}catch(e){toast(e.message)}};sec.onchange=async()=>{try{const n=await api('/quiz/options?branch='+encodeURIComponent(branch.value)+'&section='+encodeURIComponent(sec.value));document.getElementById('quizNotice').textContent=n.source}catch(e){toast(e.message)}};document.getElementById('quizNotice').textContent=d.source;await loadQuizHistory()}catch(e){document.getElementById('quizArea').innerHTML=`<div class="card"><p class="muted">${esc(e.message)}</p></div>`}
}
async function suggestQuizTopics(){
 const select=document.getElementById('quizSubject'),opt=select?.options[select.selectedIndex],code=opt?.dataset?.code||'',name=opt?.dataset?.name||opt?.textContent||'';
 const branch=document.getElementById('quizBranch')?.value||'ALL',box=document.getElementById('quizTopicSuggestions');if(!box)return;
 if(!code&&!name){box.innerHTML='<div class="list-item">Choose a subject first.</div>';return}
 box.innerHTML='<div class="list-item"><span class="muted">Finding topics repeated across different exam years…</span></div>';
 try{
  const params=new URLSearchParams(code?{subjectCode:code}:{subject:name});if(branch!=='ALL')params.set('branch',branch);
  const d=await api('/pyq/analysis/subject?'+params.toString()),topics=d.topics||[],questions=d.repeatedQuestions||[],similar=d.repeatedSimilar||[];
  const years=x=>(x.years||[]).map(esc).join(', ');
  box.innerHTML=`<div class="card"><div class="eyebrow">CROSS-YEAR STUDY PRIORITIES</div><h3>${esc(d.subjectCode||'')} · ${esc(d.subject||name)}</h3>${topics.length?`<h4>Topics to prioritize</h4><div class="grid-2">${topics.slice(0,8).map(x=>`<div class="list-item"><b>${esc(x.topic)}</b><p class="muted">Repeated across ${Number(x.yearCount||(x.years||[]).length)} years: ${years(x)}</p></div>`).join('')}</div>`:'<p class="muted">No reliable repeated topics found across multiple years in the indexed text.</p>'}${questions.length?`<h4 style="margin-top:14px">Repeated questions</h4><div class="list">${questions.slice(0,5).map(x=>`<div class="list-item"><b>${esc(x.question)}</b><p class="muted">Years: ${years(x)}</p></div>`).join('')}</div>`:''}${!questions.length&&similar.length?`<h4 style="margin-top:14px">Similar question patterns</h4><div class="list">${similar.slice(0,5).map(x=>`<div class="list-item"><b>${esc(x.question)}</b><p class="muted">Years: ${years(x)}</p></div>`).join('')}</div>`:''}</div>`;
 }catch(e){box.innerHTML=`<div class="list-item"><span class="muted">${esc(e.message)}</span></div>`}
}
async function startAKTUQuiz(){const mode=document.getElementById('quizMode')?.value||'practice';if(quizTimer){clearInterval(quizTimer);quizTimer=null}quizTimedOut=false;const branch=document.getElementById('quizBranch').value,subjectSelect=document.getElementById('quizSubject'),opt=subjectSelect.options[subjectSelect.selectedIndex],subject=opt?.dataset?.name||opt?.textContent||subjectSelect.value,subjectCode=opt?.dataset?.code||'',section=document.getElementById('quizSection').value,difficulty=document.getElementById('quizDifficulty').value,count=Number(document.getElementById('quizCount').value),area=document.getElementById('quizArea');if(!subject||!subjectSelect.value)return toast('Choose a subject');area.innerHTML='<div class="card"><div class="loading">Analysing historical papers, repeated topics and building your quiz…</div></div>';try{activeQuiz=await api('/quiz/generate',{method:'POST',body:{branch,section,subject,subjectCode,difficulty,count,mode}});activeQuiz.mode=mode;activeQuizAnswers={};renderActiveQuiz()}catch(e){area.innerHTML=`<div class="card"><h3>Quiz could not be generated</h3><p class="muted">${esc(e.message)}</p><p class="muted">For a quiz generated from historical paper evidence, configure AI_API_URL and AI_API_KEY in backend/.env. The PYQ repetition analysis remains available without AI.</p></div>`}}
function renderActiveQuiz(){const area=document.getElementById('quizArea');if(!activeQuiz||!area)return;if(quizTimer){clearInterval(quizTimer);quizTimer=null}quizTimedOut=false;const summary=activeQuiz.sourceSummary||{};area.innerHTML=`<div class="card"><div class="actions" style="justify-content:space-between"><div><h2>${esc(activeQuiz.subjectCode||'')} ${esc(activeQuiz.subject)} Quiz</h2><p class="muted">Branch ${esc(activeQuiz.branch||'ALL')} · ${esc(activeQuiz.difficulty)} · ${activeQuiz.questions.length} questions · ${esc(activeQuiz.provider)}</p></div><span class="pill">${summary.paperCount||0} source papers</span></div>${activeQuiz.mode==='exam'?'<div class="list-item"><b>⏱ Exam mode</b><p id="quizClock" class="stat">Starting timer…</p><small class="muted">90 seconds per question. Unanswered questions count as incorrect when time expires.</small></div>':''}${summary.priorityTopics?.length?`<div class="list-item"><b>Recommended topics from cross-year repeats</b><div class="grid-2" style="margin-top:8px">${summary.priorityTopics.slice(0,8).map(x=>`<div><b>${esc(x.topic)}</b><p class="muted">Repeated across ${esc(x.yearCount||((x.years||[]).length))} years${x.years?.length?': '+x.years.map(esc).join(', '):''}</p></div>`).join('')}</div></div>`:''}${activeQuiz.questions.map((q,i)=>`<div class="list-item" style="margin-top:14px"><b>Q${i+1}. ${esc(q.question)}</b>${q.topic?`<p class="muted" style="margin:5px 0">Topic: ${esc(q.topic)}${q.sourceYears?.length?' · Historical years: '+q.sourceYears.map(esc).join(', '):''}</p>`:''}<div style="display:grid;gap:8px;margin-top:12px">${q.options.map((o,j)=>`<label style="display:flex;gap:9px;align-items:flex-start;cursor:pointer"><input type="radio" name="${q.id}" value="${j}" onchange="activeQuizAnswers['${q.id}']=Number(this.value)"><span>${String.fromCharCode(65+j)}. ${esc(o)}</span></label>`).join('')}</div></div>`).join('')}<p class="muted" style="margin-top:12px">${esc(activeQuiz.note||'Practice questions are not official answer keys.')}</p><div class="actions" style="margin-top:16px"><button class="btn" onclick="finishAKTUQuiz()">Submit answers & see analysis</button><button class="btn ghost" onclick="page('quiz')">Cancel</button></div></div>`;if(activeQuiz.mode==='exam'){let remaining=activeQuiz.questions.length*90;const clock=document.getElementById('quizClock');const tick=()=>{if(!clock)return;clock.textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')} remaining`;if(remaining<=0){clearInterval(quizTimer);quizTimer=null;quizTimedOut=true;for(const q of activeQuiz.questions)if(!Number.isInteger(activeQuizAnswers[q.id]))activeQuizAnswers[q.id]=-1;finishAKTUQuiz(true);return}remaining--};tick();quizTimer=setInterval(tick,1000)}}
async function finishAKTUQuiz(fromTimer=false){if(!activeQuiz)return;const qs=activeQuiz.questions,missing=qs.filter(q=>!Number.isInteger(activeQuizAnswers[q.id])||activeQuizAnswers[q.id]<0);if(missing.length&&!quizTimedOut)return toast(`Answer all questions first (${missing.length} remaining)`);if(quizTimer){clearInterval(quizTimer);quizTimer=null}const score=qs.reduce((n,q)=>n+(activeQuizAnswers[q.id]===q.correctAnswerIndex?1:0),0),percent=Math.round(score/qs.length*100),answers=qs.map(q=>({questionId:q.id,selectedIndex:activeQuizAnswers[q.id],correct:activeQuizAnswers[q.id]===q.correctAnswerIndex,question:q.question,topic:q.topic||activeQuiz.subject,sourceYears:q.sourceYears||[]}));const area=document.getElementById('quizArea');area.innerHTML='<div class="card"><div class="loading">Saving your result and updating topic-level performance…</div></div>';try{const result=await api('/quiz/submit',{method:'POST',body:{score,total:qs.length,branch:activeQuiz.branch,subject:activeQuiz.subject,subjectCode:activeQuiz.subjectCode,section:activeQuiz.section,difficulty:activeQuiz.difficulty,mode:activeQuiz.mode||'practice',answers}});area.innerHTML=`<div class="card hero"><div class="eyebrow" style="color:#c4b5fd">Quiz completed</div><h2>${score}/${qs.length} · ${percent}%</h2><p>${esc(result.feedback||'Performance saved.')}</p><div class="progress"><i style="width:${percent}%"></i></div><p class="muted" style="margin-top:12px">Your result is saved with branch, subject and missed-topic information.</p>${result.weakTopics?.length?`<h3>Topics to revise next</h3>${result.weakTopics.map(x=>`<div class="list-item"><b>${esc(x.topic)}</b><span class="muted"> · ${x.misses} missed question(s)</span></div>`).join('')}`:'<p class="muted">No weak topic recorded for this attempt.</p>'}</div><div class="card" style="margin-top:14px"><h3>Answer review</h3>${qs.map((q,i)=>{const ok=activeQuizAnswers[q.id]===q.correctAnswerIndex;return `<div class="list-item" style="margin-top:10px"><b>${ok?'✅':'❌'} Q${i+1}. ${esc(q.question)}</b><p class="muted">Your answer: ${Number.isInteger(activeQuizAnswers[q.id])&&activeQuizAnswers[q.id]>=0?esc(q.options[activeQuizAnswers[q.id]]):'Not answered'}</p>${!ok?`<p><b>Correct answer:</b> ${esc(q.options[q.correctAnswerIndex])}</p>`:''}<p>${esc(q.explanation)}</p></div>`}).join('')}<div class="actions" style="margin-top:14px"><button class="btn" onclick="startAKTUQuiz()">Try another set</button><button class="btn secondary" onclick="loadQuizHistory()">View performance</button></div></div>`;await loadQuizHistory()}catch(e){area.innerHTML=`<div class="card"><p class="muted">${esc(e.message)}</p></div>`}}
async function loadQuizHistory(){const box=document.getElementById('quizPerformance');if(!box)return;try{const d=await api('/quiz/history');const attempts=d.attempts||[],avg=attempts.length?Math.round(attempts.reduce((s,x)=>s+(Number(x.percentage)||0),0)/attempts.length):0;box.innerHTML=`<div class="grid">${[['Total attempts',attempts.length],['Average score',avg+'%'],['Subjects practised',(d.bySubject||[]).length]].map(x=>`<div class="card"><div class="metric-label">${x[0]}</div><div class="stat">${x[1]}</div></div>`).join('')}</div><br><div class="grid-2"><div class="card"><h3>📚 Branch & subject performance</h3>${(d.bySubject||[]).map(x=>`<div class="list-item" style="margin-top:10px"><div class="actions" style="justify-content:space-between"><b>${esc(x.subject)}</b><b>${x.average}%</b></div><div class="progress" style="margin:8px 0"><i style="width:${Math.min(100,x.average)}%"></i></div><small class="muted">${x.attempts} attempt(s) · latest ${x.latest}% · best ${x.best}%</small></div>`).join('')||'<p class="muted">Complete your first quiz to see subject analytics.</p>'}</div><div class="card"><h3>🎯 Topics to revise</h3>${(d.weakTopics||[]).map(x=>`<div class="list-item" style="margin-top:8px"><div class="actions" style="justify-content:space-between"><b>${esc(x.topic)}</b><span class="pill">${x.misses} misses</span></div></div>`).join('')||'<p class="muted">Weak-topic trends appear after you submit quizzes.</p>'}<h3 style="margin-top:18px">🕘 Recent attempts</h3>${attempts.slice(0,10).map(x=>`<div class="list-item" style="margin-top:8px"><div class="actions" style="justify-content:space-between"><b>${esc(x.subjectCode?x.subjectCode+' · ':'')}${esc(x.subject||'General')}</b><span class="pill">${x.percentage}%</span></div><small class="muted">${esc(x.branch||'ALL branches')} · ${esc(x.section||'No section')} · ${esc(x.difficulty||'Mixed')} · ${esc(x.mode||'practice')} · ${new Date(x.createdAt).toLocaleString()}</small><p class="muted">${x.score}/${x.total} correct</p></div>`).join('')||'<p class="muted">No attempts recorded yet.</p>'}</div></div>`}catch(e){box.innerHTML=`<div class="card"><p class="muted">${esc(e.message)}</p></div>`}}
function resume(c){c.innerHTML=`<div class="card"><div class="actions" style="justify-content:space-between"><div><div class="icon-box">📄</div><h2>AI Resume Intelligence</h2><p class="muted">Upload your resume and let AI review ATS compatibility, skills, projects, experience, impact and role fit.</p></div><span class="pill">AI-powered</span></div><div class="form-grid" style="margin-top:16px"><input class="field full" id="targetRole" placeholder="Target role (optional, e.g. Software Engineer, Data Analyst)"><input class="field full" id="resumeFile" type="file" accept=".pdf,.docx"></div><div class="actions" style="margin-top:10px"><button class="btn" onclick="analyzeResume()">✨ Analyze with AI</button><span class="muted">PDF or DOCX · your file is processed temporarily</span></div><div id="resumeResult" style="margin-top:18px"></div></div>`}
const resumeList=(title,items,icon='•')=>items?.length?`<div class="card"><h3>${icon} ${title}</h3><div class="list">${items.map(x=>`<div class="list-item">${esc(x)}</div>`).join('')}</div></div>`:'';
async function analyzeResume(){const f=document.getElementById('resumeFile').files[0],box=document.getElementById('resumeResult');if(!f)return toast('Choose a PDF or DOCX');if(f.size>8*1024*1024)return toast('Resume must be smaller than 8 MB');const fd=new FormData();fd.append('resume',f);fd.append('targetRole',document.getElementById('targetRole').value.trim());box.innerHTML='<div class="card"><div class="loading">🤖 AI is reading your resume and evaluating ATS, skills, projects, experience and role fit…</div></div>';try{const d=await api('/resume/analyze',{method:'POST',body:fd});const score=Math.round(d.score||0),ats=Math.round(d.atsScore||0),match=Math.round(d.jobMatch||0);const scoreTone=score>=80?'Excellent':score>=65?'Good':score>=50?'Needs improvement':'Needs major improvement';box.innerHTML=`<div class="resume-ai-grid"><div class="card resume-score-card"><div class="eyebrow">Overall AI score</div><div class="resume-score">${score}<small>/100</small></div><b>${scoreTone}</b><p class="muted">${esc(d.summary||'AI review completed.')}</p></div><div class="card"><div class="metric-label">ATS compatibility</div><div class="stat">${ats}%</div><div class="progress"><i style="width:${ats}%"></i></div><p class="muted">Parsing, structure, keywords and recruiter readability.</p></div><div class="card"><div class="metric-label">${d.targetRole?'Target-role match':'Role match'}</div><div class="stat">${d.targetRole?match+'%':'—'}</div>${d.targetRole?`<div class="progress"><i style="width:${match}%"></i></div><p class="muted">Fit for <b>${esc(d.targetRole)}</b> based only on resume evidence.</p>`:'<p class="muted">Add a target role before analysis for personalized job matching.</p>'}</div></div><br><div class="grid-2"><div>${resumeList('Key strengths',d.strengths,'✅')}${resumeList('Priority improvements',d.weaknesses,'⚠️')}${resumeList('AI recommendations',d.suggestions,'🚀')}</div><div><div class="card"><h3>🧠 Skills & keywords</h3><p><b>Detected</b></p><div>${(d.skills||[]).map(x=>`<span class="pill" style="margin:3px">${esc(x)}</span>`).join('')||'<span class="muted">No clear skills detected.</span>'}</div><p style="margin-top:14px"><b>Missing / useful keywords</b></p><div>${(d.missing||[]).map(x=>`<span class="pill resume-missing" style="margin:3px">${esc(x)}</span>`).join('')||'<span class="muted">No major gaps identified.</span>'}</div></div>${(d.keywords||[]).length?resumeList('Recommended keywords',d.keywords,'🔑'):''}</div></div><br><div class="card"><h3>📊 Section-by-section analysis</h3><div class="resume-sections">${(d.sections||[]).map(x=>`<div class="list-item"><div class="actions" style="justify-content:space-between"><b>${esc(x.title)}</b><b>${Number(x.score)||0}%</b></div><div class="progress" style="margin:8px 0"><i style="width:${Math.min(100,Number(x.score)||0)}%"></i></div><span class="muted">${esc(x.detail)}</span></div>`).join('')||'<div class="empty">No section-level details returned.</div>'}</div></div>${resumeList('Project analysis',d.projects,'🛠️')}${resumeList('Experience analysis',d.experience,'💼')}${resumeList('Suggested bullet rewrites',d.rewrites,'✍️')}<div class="card" style="margin-top:16px"><div class="actions"><button class="btn secondary" onclick="page('resume')">Analyze another resume</button>${d.targetRole?`<span class="pill">Target: ${esc(d.targetRole)}</span>`:''}</div></div>`}catch(e){box.innerHTML='';toast(e.message)}}

async function interview(c){c.innerHTML=`<div class="card"><div class="icon-box">🎤</div><h2>Mock Interview Assistant</h2><p class="muted">Practice technical and HR questions and structure answers using STAR.</p><button class="btn" onclick="newInterview()">Generate question</button><div id="interviewBox" style="margin-top:18px"></div></div>`;newInterview()}async function newInterview(){const d=await api('/ai/interview',{method:'POST',body:{role:'software developer'}});document.getElementById('interviewBox').innerHTML=`<h3>${esc(d.question)}</h3><textarea class="field" id="ans" rows="7" placeholder="Type your answer…"></textarea><button class="btn" style="margin-top:8px" onclick="toast('Feedback: '+${JSON.stringify(d.feedback)})">Evaluate answer</button><p class="muted" style="margin-top:12px">${esc(d.feedback)}</p>`}
async function progress(c){const d=await api('/progress');c.innerHTML=`<div class="grid">${[['Attendance',d.attendance],['Quiz score',d.quizScore],['Resume score',d.resumeScore],['Readiness',d.readiness]].map(x=>`<div class="card"><div class="metric-label">${x[0]}</div><div class="stat">${x[1]}%</div><div class="progress"><i style="width:${Math.min(100,Number(x[1])||0)}%"></i></div></div>`).join('')}</div><br><div class="card"><h2>Attendance Predictor</h2><div class="form-grid"><input class="field" id="att" placeholder="Current attendance %"><input class="field" id="attended" placeholder="Classes attended"><input class="field" id="total" placeholder="Classes conducted"><input class="field" id="future" placeholder="Future classes"><input class="field" id="target" placeholder="Target %" value="75"></div><button class="btn" style="margin-top:10px" onclick="predictAtt()">Predict</button><div id="attResult"></div></div>`}async function predictAtt(){const d=await api('/attendance/predict',{method:'POST',body:{current:document.getElementById('att').value,attended:document.getElementById('attended').value,total:document.getElementById('total').value,future:document.getElementById('future').value,target:document.getElementById('target').value}});document.getElementById('attResult').innerHTML=`<div class="list-item" style="margin-top:15px"><b>Predicted attendance: ${d.predicted}%</b><br><span class="muted">Target ${d.target}% · Additional classes needed: ${d.classesNeeded}</span></div>`}
async function emergency(c){const d=await api('/emergency');c.innerHTML=`<div class="grid">${d.map(x=>`<div class="card feature-card"><div class="icon-box">🚨</div><h2>${esc(x.name)}</h2><p class="muted">${esc(x.contact)}</p></div>`).join('')}</div>`}
if(token)render();else login();
